package com.travbook.journeys.adapter.out.persistence;
import com.travbook.journeys.application.port.out.*;
import com.travbook.journeys.domain.model.*;
import com.travbook.journeys.domain.model.Journey.Booking;
import com.travbook.journeys.domain.model.Journey.Kind;
import com.travbook.journeys.domain.model.Journey.Status;
import com.travbook.journeys.domain.model.Care.*;
import com.travbook.shared.domain.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import static com.travbook.shared.domain.DomainFailure.Code.*;
public final class JdbcJourneyCare implements JourneyCareStore {
 private final JdbcClient jdbc;private final TransactionTemplate tx;private final ObjectMapper json;private final Clock clock;private final JourneyStore base;
 public JdbcJourneyCare(JdbcClient j,TransactionTemplate t,ObjectMapper m,Clock c,JourneyStore b){jdbc=j;tx=t;json=m;clock=c;base=b;}
 private DomainFailure missing(){return new DomainFailure(NOT_FOUND,"Journey aftercare resource not found.");}
 private Booking lock(UUID owner,UUID id){jdbc.sql("select w.booking_id from journey_work w join journey_booking b on b.id=w.booking_id where b.id=:id and b.customer_id=:owner for update of w,b").param("id",id).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);return base.booking(owner,id);}
 private void available(UUID id){if(jdbc.sql("select count(*) from journey_care_action a where (a.booking_id=:id or a.id in(select action_id from journey_replacement where replacement_id=:id)) and a.status in('PENDING','WAITING','REVIEW')").param("id",id).query(Integer.class).single()>0)Journey.conflict("Another aftercare or replacement operation is still unresolved.");}
 private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private Optional<UUID> replay(UUID owner,String op,String key,String f){return base.replay(owner,op,key,f);}
 private boolean command(UUID owner,String op,String key,String f,UUID resource){return jdbc.sql("insert into journey_command(customer_id,operation,command_key,fingerprint,resource_id) values(:owner,:op,:key,:f,:id) on conflict do nothing").param("owner",owner).param("op",op).param("key",key).param("f",f).param("id",resource).update()==1;}
 private List<Action> actions(UUID id){return jdbc.sql("select payload::text from journey_care_action where booking_id=:id order by created_at,id").param("id",id).query(String.class).list().stream().map(s->json.readValue(s,Action.class)).toList();}
 private List<String> active(Booking b){var gone=Set.copyOf(jdbc.sql("select component_id from journey_component_cancelled where booking_id=:id").param("id",b.id()).query(String.class).list());return b.quote().selection().components().stream().map(c->c.id()).filter(id->!gone.contains(id)).toList();}
 private Optional<UUID> balancePayment(UUID id){return jdbc.sql("select payment_id from journey_balance where booking_id=:id and state='PAID'").param("id",id).query(UUID.class).optional();}
 private boolean funded(Booking b,Terms t){return b.payment()==Journey.Payment.CAPTURED&&(t.fundingPlan()==Plan.FULL||balancePayment(b.id()).isPresent());}
 public Summary summary(UUID owner,UUID id){return tx.execute(t->{var b=lock(owner,id);var terms=base.terms(b.quote().id());var records=actions(id);var active=active(b);var paid=b.payment()==Journey.Payment.CAPTURED?terms.firstAmount().decimal():BigDecimal.ZERO;if(balancePayment(id).isPresent())paid=paid.add(terms.balanceAmount().decimal());BigDecimal settled=BigDecimal.ZERO,pending=BigDecimal.ZERO;for(var a:records)for(var part:a.refunds()){if(part.status()==RefundState.SUCCEEDED)settled=settled.add(part.amount().decimal());else if(a.supplierApplied())pending=pending.add(part.amount().decimal());}if(b.refund()==Journey.Refund.SUCCEEDED&&records.isEmpty())settled=paid;else if(b.payment()==Journey.Payment.CAPTURED&&records.isEmpty()&&(b.status()==Status.FAILED||b.status()==Status.CANCELLED||b.refund()==Journey.Refund.PENDING))pending=paid;BigDecimal outstanding=active.isEmpty()||b.status()==Status.FAILED||b.status()==Status.CANCELLED?BigDecimal.ZERO:b.payment()!=Journey.Payment.CAPTURED?b.quote().selection().total().decimal():funded(b,terms)?BigDecimal.ZERO:terms.balanceAmount().decimal();String status=b.status()==Status.REVIEW||records.stream().anyMatch(a->a.status()==State.REVIEW)?"REVIEW":b.status()==Status.PAYMENT_PENDING||records.stream().anyMatch(a->a.type()==Type.BALANCE&&!a.terminal())?"PAYMENT_PENDING":pending.signum()>0?"REFUND_PENDING":b.status()==Status.CANCELLED?"CANCELLED":b.status()==Status.FAILED&&b.refund()==Journey.Refund.SUCCEEDED?"REFUNDED":paid.signum()==0?"UNPAID":outstanding.signum()==0?"PAID":terms.balanceDue()!=null&&!clock.instant().isBefore(terms.balanceDue())?"OVERDUE":"DEPOSIT_PAID";boolean visible=b.status()==Status.CONFIRMED&&funded(b,terms)&&!active.isEmpty()&&records.stream().noneMatch(a->!a.terminal()&&!a.supplierApplied()&&a.type()==Type.CANCEL);var from=jdbc.sql("select booking_id from journey_replacement where replacement_id=:id").param("id",id).query(UUID.class).optional().orElse(null);var to=jdbc.sql("select r.replacement_id from journey_replacement r join journey_care_action a on a.id=r.action_id where r.booking_id=:id order by a.created_at desc,a.id desc limit 1").param("id",id).query(UUID.class).optional().orElse(null);var shown=new ArrayList<>(records);if(from!=null)actions(from).stream().filter(a->id.equals(a.replacementId())).forEach(shown::add);return new Summary(b,terms,new Funding(terms.fundingPlan(),TravelMoney.inr(paid),TravelMoney.inr(settled),TravelMoney.inr(pending),TravelMoney.inr(outstanding),terms.balanceDue(),status),active,List.copyOf(shown),visible,b.quote().version()==1,from,to);});}
 private List<RefundPart> parts(Booking b,Terms terms,List<String> selected){var allocation=terms.firstAllocations(b.quote());var first=selected.stream().map(id->allocation.get(id).decimal()).reduce(BigDecimal.ZERO,(a,c)->a.add(c));var amount=b.quote().selection().components().stream().filter(c->selected.contains(c.id())).map(c->c.amount().decimal()).reduce(BigDecimal.ZERO,(a,c)->a.add(c));var parts=new ArrayList<RefundPart>();if(first.signum()>0)parts.add(new RefundPart(b.id(),TravelMoney.inr(first),null,RefundState.NOT_STARTED));var second=amount.subtract(first);var payment=balancePayment(b.id());if(payment.isPresent()&&second.signum()>0)parts.add(new RefundPart(payment.get(),TravelMoney.inr(second),null,RefundState.NOT_STARTED));return List.copyOf(parts);}
 private CancellationQuote cancellation(Booking b,List<String> selected){var terms=base.terms(b.quote().id());var chosen=Care.validateCancellation(b,terms,selected,active(b),funded(b,terms),clock.instant());var refunds=parts(b,terms,chosen);var total=refunds.stream().map(p->p.amount().decimal()).reduce(BigDecimal.ZERO,(a,c)->a.add(c));var face=b.quote().selection().components().stream().filter(c->chosen.contains(c.id())).map(c->c.amount().decimal()).reduce(BigDecimal.ZERO,(a,c)->a.add(c));var until=clock.instant().plusSeconds(120);if(b.quote().selection().cancelUntil().isBefore(until))until=b.quote().selection().cancelUntil();return new CancellationQuote(UUID.randomUUID(),b.id(),b.version(),chosen,refunds,TravelMoney.inr(total),TravelMoney.inr(face.subtract(total)),until,"MOCK");}
 private CancellationQuote cancellationRecord(UUID owner,UUID id){return jdbc.sql("select payload::text from journey_care_quote where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(p->json.readValue(p,CancellationQuote.class)).orElseThrow(this::missing);}
 public CancellationQuote quoteCancellation(UUID owner,UUID id,List<String> ids,String key,UUID correlation){String f=hash(id+":"+ids);return tx.execute(t->{UUID qid=UUID.randomUUID();if(!command(owner,"CARE_QUOTE",key,f,qid))return cancellationRecord(owner,replay(owner,"CARE_QUOTE",key,f).orElseThrow());var b=lock(owner,id);available(id);var source=cancellation(b,ids);var q=new CancellationQuote(qid,id,b.version(),source.componentIds(),source.refunds(),source.refundAmount(),source.unpaidAmountCancelled(),source.expiresAt(),"MOCK");jdbc.sql("insert into journey_care_quote(id,booking_id,customer_id,payload) values(:id,:b,:owner,cast(:p as jsonb))").param("id",qid).param("b",id).param("owner",owner).param("p",json.writeValueAsString(q)).update();return q;});}
 private Action action(UUID owner,UUID id){return jdbc.sql("select payload::text from journey_care_action where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(p->json.readValue(p,Action.class)).orElseThrow(this::missing);}
 private void saveBooking(Booking b,long version){if(jdbc.sql("update journey_booking set version=:v,status=:s,payload=cast(:p as jsonb) where id=:id and version=:old").param("v",b.version()).param("s",b.status().name()).param("p",json.writeValueAsString(b)).param("id",b.id()).param("old",version).update()!=1)Journey.conflict("Booking changed concurrently.");}
 private void insert(Action a){jdbc.sql("insert into journey_care_action(id,booking_id,customer_id,type,status,version,created_at,payload) values(:id,:b,:owner,:type,:status,:v,:at,cast(:p as jsonb))").param("id",a.id()).param("b",a.booking().id()).param("owner",a.booking().quote().owner()).param("type",a.type().name()).param("status",a.status().name()).param("v",a.version()).param("at",Timestamp.from(a.createdAt())).param("p",json.writeValueAsString(a)).update();jdbc.sql("insert into journey_care_work(action_id,state,next_at) values(:id,'READY',:now)").param("id",a.id()).param("now",Timestamp.from(clock.instant())).update();event(a);}
 private Action create(UUID id,Booking b,Type type,Phase step,List<String> components,List<RefundPart> refunds,TravelMoney amount,Instant deadline,UUID child,boolean delay,boolean decline,boolean loss,UUID correlation){return new Action(id,1,b,type,State.PENDING,step,components,refunds,amount,deadline,child,false,delay,decline,loss,0,null,clock.instant(),clock.instant(),correlation);}
 public Action cancel(UUID owner,UUID id,UUID quote,boolean delay,boolean loss,String key,UUID correlation){String f=hash(id+":"+quote+":"+delay+":"+loss);return tx.execute(t->{UUID aid=UUID.randomUUID();if(!command(owner,"CARE_CANCEL",key,f,aid))return action(owner,replay(owner,"CARE_CANCEL",key,f).orElseThrow());var b=lock(owner,id);available(id);var q=cancellationRecord(owner,quote);if(!q.bookingId().equals(id)||q.bookingVersion()!=b.version()||!clock.instant().isBefore(q.expiresAt()))Journey.conflict("Cancellation quotation expired or booking changed.");var current=cancellation(b,q.componentIds());if(!current.refunds().equals(q.refunds()))Journey.conflict("Funding changed; request a new cancellation quote.");var a=create(aid,b,Type.CANCEL,Phase.CANCEL,q.componentIds(),q.refunds(),q.refundAmount(),q.expiresAt(),null,delay,false,loss,correlation);insert(a);jdbc.sql("insert into journey_care_quote_use(action_id,quote_id) values(:a,:q)").param("a",a.id()).param("q",q.id()).update();saveBooking(b.careState(Status.CANCELLATION_PENDING,b.refund(),clock.instant()),b.version());return a;});}
 public Action balance(UUID owner,UUID id,boolean decline,boolean loss,String key,UUID correlation){String f=id+":"+decline+":"+loss;return tx.execute(t->{UUID aid=UUID.randomUUID();if(!command(owner,"CARE_BALANCE",key,f,aid))return action(owner,replay(owner,"CARE_BALANCE",key,f).orElseThrow());var b=lock(owner,id);available(id);var terms=base.terms(b.quote().id());if(b.status()!=Status.CONFIRMED||b.step()!=Journey.Step.DONE||terms.fundingPlan()!=Plan.DEPOSIT||funded(b,terms)||!clock.instant().isBefore(terms.balanceDue())||active(b).size()!=b.quote().selection().components().size())Journey.conflict("The balance is not payable at the current state or deadline.");var a=create(aid,b,Type.BALANCE,Phase.VALIDATE,List.of(),List.of(),terms.balanceAmount(),terms.balanceDue(),null,false,decline,loss,correlation);insert(a);jdbc.sql("update journey_balance set state='RUNNING',action_id=:action where booking_id=:id and state='DUE'").param("action",aid).param("id",id).update();saveBooking(b.careState(b.status(),b.refund(),clock.instant()),b.version());return a;});}
 public Optional<Replacement> replacement(UUID quote){return jdbc.sql("select booking_id,booking_version from journey_replacement_quote where quote_id=:id").param("id",quote).query((r,n)->{var id=r.getObject(1,UUID.class);var b=json.readValue(jdbc.sql("select payload::text from journey_booking where id=:id").param("id",id).query(String.class).single(),Booking.class);return new Replacement(id,r.getLong(2),b.quote().selection().total());}).optional();}
 public boolean replacementQuote(UUID id){return replacement(id).isPresent();}
 private void reschedulable(Booking b){if(!base.terms(b.quote().id()).rescheduling()||b.status()!=Status.CONFIRMED||b.step()!=Journey.Step.DONE||!clock.instant().isBefore(b.quote().selection().cancelUntil())||active(b).size()!=b.quote().selection().components().size())Journey.conflict("This bus booking is not eligible for full replacement.");available(b.id());}
 public Journey.Quote replacementQuote(UUID owner,UUID id,long version,Journey.Quote q,Terms terms,String key,String fingerprint,UUID correlation){return tx.execute(t->{var b=lock(owner,id);var old=base.replay(owner,"QUOTE",key,"V2:"+fingerprint);if(old.isPresent())return base.quote(owner,old.get()).quote();reschedulable(b);if(b.version()!=version||q.selection().request().kind()!=Kind.BUS||!q.selection().supplier().equals(b.quote().selection().supplier())||!q.selection().title().equals(b.quote().selection().title())||!q.selection().passengerAges().equals(b.passengers().stream().map(person->person.age()).toList())||q.selection().departureAt().equals(b.quote().selection().departureAt()))Journey.conflict("Choose a different departure on the same provider/route with the same passenger ages.");var saved=base.createAdvancedQuote(q,terms,key,fingerprint,correlation);jdbc.sql("insert into journey_replacement_quote(quote_id,booking_id,booking_version,customer_id) values(:q,:id,:v,:owner)").param("q",saved.id()).param("id",id).param("v",version).param("owner",owner).update();return saved;});}
 public Action replace(UUID owner,UUID id,UUID quote,long version,String key,UUID correlation){String f=id+":"+quote+":"+version;return tx.execute(t->{UUID aid=UUID.randomUUID();if(!command(owner,"CARE_REPLACE",key,f,aid))return action(owner,replay(owner,"CARE_REPLACE",key,f).orElseThrow());var b=lock(owner,id);reschedulable(b);var bind=replacement(quote).orElseThrow(this::missing);if(!bind.bookingId().equals(id)||bind.version()!=version||b.version()!=version)Journey.conflict("Replacement quotation belongs to a different booking version.");var q=base.quote(owner,quote);q.quote().valid(clock.instant());if(q.acceptedAt()==null)throw new DomainFailure(QUOTE_NOT_ACCEPTED,"Accept replacement terms first.");var child=base.book(owner,quote,b.passengers(),b.email(),b.scenario(),"replace-"+aid,hash(f),correlation);var cq=cancellation(b,active(b));var a=create(aid,b,Type.RESCHEDULE,Phase.WAIT_REPLACEMENT,cq.componentIds(),cq.refunds(),cq.refundAmount(),q.quote().expiresAt().plusSeconds(60),child.id(),false,false,b.scenario()==Journey.Scenario.RESPONSE_LOST,correlation);insert(a);jdbc.sql("insert into journey_replacement(booking_id,replacement_id,action_id,customer_id) values(:id,:child,:a,:owner)").param("id",id).param("child",child.id()).param("a",aid).param("owner",owner).update();saveBooking(b.careState(b.status(),b.refund(),clock.instant()),b.version());return a;});}
 private void event(Action a){event(a,a.id(),a.correlationId());}
 private void event(Action a,UUID cause,UUID correlation){UUID id=UUID.randomUUID();var e=new LinkedHashMap<String,Object>();e.put("eventId",id);e.put("aggregateId",a.id());e.put("aggregateVersion",a.version());e.put("schemaVersion",1);e.put("eventType","JourneyCare"+a.type()+a.status());e.put("timestamp",clock.instant());e.put("correlationId",correlation);e.put("causationId",cause);e.put("producer","journey-care");e.put("mode","MOCK");e.put("payload",Map.of("bookingId",a.booking().id(),"type",a.type(),"status",a.status(),"step",a.step()));jdbc.sql("insert into journey_care_outbox(id,aggregate_id,aggregate_version,envelope) values(:id,:a,:v,cast(:p as jsonb))").param("id",id).param("a",a.id()).param("v",a.version()).param("p",json.writeValueAsString(e)).update();}
 public Optional<Claim> claim(){return tx.execute(t->{var id=jdbc.sql("select action_id from journey_care_work where state in('READY','RUNNING') and next_at<=:now and (lease_until is null or lease_until<clock_timestamp()) order by next_at,action_id for update skip locked limit 1").param("now",Timestamp.from(clock.instant())).query(UUID.class).optional();if(id.isEmpty())return Optional.empty();UUID token=UUID.randomUUID();int attempts=jdbc.sql("update journey_care_work set state='RUNNING',attempts=attempts+1,lease_token=:token,lease_until=clock_timestamp()+interval '15 seconds' where action_id=:id returning attempts").param("token",token).param("id",id.get()).query(Integer.class).single();var a=json.readValue(jdbc.sql("select payload::text from journey_care_action where id=:id").param("id",id.get()).query(String.class).single(),Action.class);return Optional.of(new Claim(a,token,attempts));});}
 private boolean owns(Claim c){return jdbc.sql("select action_id from journey_care_work where action_id=:id and state='RUNNING' and lease_token=:token and lease_until>clock_timestamp() for update").param("id",c.action().id()).param("token",c.token()).query(UUID.class).optional().isPresent();}
 private void saveAction(Action a,long before){if(jdbc.sql("update journey_care_action set status=:s,version=:v,payload=cast(:p as jsonb) where id=:id and version=:old").param("s",a.status().name()).param("v",a.version()).param("p",json.writeValueAsString(a)).param("id",a.id()).param("old",before).update()!=1)Journey.conflict("Concurrent aftercare update.");}
 private void wake(Action a){jdbc.sql("update journey_care_work set state=:s,attempts=0,next_at=:at,lease_token=null,lease_until=null where action_id=:id").param("s",a.status()==State.REVIEW?"REVIEW":a.terminal()?"DONE":"READY").param("at",Timestamp.from(a.step()==Phase.WAIT_REPLACEMENT?clock.instant().plusSeconds(2):clock.instant())).param("id",a.id()).update();}
 public boolean complete(Claim c,Action next){return tx.execute(t->{if(!owns(c))return false;var current=action(c.action().booking().quote().owner(),next.id());if(current.version()!=c.action().version())return false;var b=lock(current.booking().quote().owner(),current.booking().id());saveAction(next,current.version());wake(next);Booking updated=b;
  if(next.status()==State.REVIEW){updated=b.review(clock.instant());jdbc.sql("insert into journey_care_review(action_id,review_version,booking_payload,action_payload) values(:id,:v,cast(:b as jsonb),cast(:a as jsonb))").param("id",next.id()).param("v",updated.version()).param("b",json.writeValueAsString(b)).param("a",json.writeValueAsString(current)).update();if(next.type()==Type.BALANCE)jdbc.sql("update journey_balance set state='REVIEW' where booking_id=:id").param("id",b.id()).update();}
  else if(next.type()==Type.RESCHEDULE&&next.step()==Phase.CANCEL&&!next.supplierApplied()){updated=b.careState(Status.CANCELLATION_PENDING,b.refund(),clock.instant());}
  else if(next.type()==Type.BALANCE&&next.terminal()){if(next.status()==State.SUCCEEDED)jdbc.sql("update journey_balance set state='PAID',payment_id=:a where booking_id=:id").param("a",next.id()).param("id",b.id()).update();else jdbc.sql("update journey_balance set state='DUE',action_id=null where booking_id=:id").param("id",b.id()).update();updated=b.careState(b.status(),b.refund(),clock.instant());}
  else if(next.supplierApplied()){for(String component:next.componentIds())jdbc.sql("insert into journey_component_cancelled(booking_id,component_id,action_id) values(:id,:c,:a) on conflict do nothing").param("id",b.id()).param("c",component).param("a",next.id()).update();boolean all=active(b).isEmpty();updated=b.careState(all?Status.CANCELLED:Status.CONFIRMED,all?(next.status()==State.SUCCEEDED?Journey.Refund.SUCCEEDED:Journey.Refund.PENDING):b.refund(),clock.instant());if(all)jdbc.sql("update journey_balance set state='CANCELLED' where booking_id=:id and state in('DUE','OVERDUE')").param("id",b.id()).update();}
  else if(next.status()==State.FAILED)updated=b.careState(Status.CONFIRMED,b.refund(),clock.instant());
  if(updated!=b){saveBooking(updated,b.version());if(updated.status()==Status.CONFIRMED&&funded(updated,base.terms(b.quote().id()))&&!active(updated).isEmpty())revision(updated);}event(next);return true;});}
 public void retry(Claim c){if(c.attempts()>=(c.action().step()==Phase.REFUND_STATUS?20:5)){complete(c,c.action().review(clock.instant()));return;}tx.executeWithoutResult(t->{if(!owns(c))return;jdbc.sql("update journey_care_work set state='READY',lease_token=null,lease_until=null,next_at=:at where action_id=:id").param("at",Timestamp.from(clock.instant().plusSeconds(Math.min(10,2*c.attempts())))).param("id",c.action().id()).update();});}
 public boolean expireBalance(){return tx.execute(t->{var id=jdbc.sql("select f.booking_id from journey_balance f join journey_booking b on b.id=f.booking_id join journey_work w on w.booking_id=b.id where f.state in('DUE','OVERDUE') and f.due_at<=:now and b.status='CONFIRMED' and not exists(select 1 from journey_care_action a where a.booking_id=b.id and a.status in('PENDING','WAITING','REVIEW')) order by f.due_at for update of w,b skip locked limit 1").param("now",Timestamp.from(clock.instant())).query(UUID.class).optional();if(id.isEmpty())return false;var b=json.readValue(jdbc.sql("select payload::text from journey_booking where id=:id").param("id",id.get()).query(String.class).single(),Booking.class);b=lock(b.quote().owner(),b.id());UUID aid=UUID.randomUUID();var chosen=active(b);var refunds=parts(b,base.terms(b.quote().id()),chosen);var amount=TravelMoney.inr(refunds.stream().map(r->r.amount().decimal()).reduce(BigDecimal.ZERO,(x,y)->x.add(y)));var a=create(aid,b,Type.CANCEL,Phase.CANCEL,chosen,refunds,amount,base.terms(b.quote().id()).balanceDue(),null,false,false,false,b.correlationId());insert(a);jdbc.sql("update journey_balance set state='OVERDUE' where booking_id=:id").param("id",b.id()).update();saveBooking(b.careState(Status.CANCELLATION_PENDING,b.refund(),clock.instant()),b.version());return true;});}
 private void revision(Booking b){var active=active(b);String content="TRAVBOOK MOCK REVISED TICKET / VOUCHER\nNOT VALID FOR TRAVEL OR CHECK-IN. NO REAL PAYMENT OR RESERVATION.\nBooking: "+b.id()+"\nSupplier: "+b.supplierReference()+"\n"+b.quote().selection().title()+"\nDeparture: "+b.quote().selection().departureAt()+" / "+b.quote().selection().timezone()+"\n"+(b.quote().selection().request().kind()==Kind.HOLIDAY&&!active.contains("activities")?"Activity itinerary removed after cancellation. Only the remaining components listed below are supplied.":String.join("\n",b.quote().selection().details()))+"\nActive components:\n"+b.quote().selection().components().stream().filter(v->active.contains(v.id())).map(v->v.description()+" INR "+v.amount().amount()).collect(java.util.stream.Collectors.joining("\n"))+"\nPassengers:\n";for(int i=0;i<b.passengers().size();i++)if(b.quote().selection().request().kind()!=Kind.BUS||active.contains(b.quote().selection().request().seats().get(i)))content+=b.passengers().get(i).name()+"\n";content+="Current funding fully paid. "+base.terms(b.quote().id()).policy()+"\n";var d=new Journey.Document(UUID.randomUUID(),b.id(),clock.instant(),hash(content),content,"MOCK");jdbc.sql("insert into journey_document_revision(id,booking_id,booking_version,payload) values(:id,:b,:v,cast(:p as jsonb)) on conflict(booking_id,booking_version) do nothing").param("id",d.id()).param("b",b.id()).param("v",b.version()).param("p",json.writeValueAsString(d)).update();}
 public Journey.Document document(UUID owner,UUID id){return tx.execute(t->{var state=summary(owner,id);if(!state.documentAvailable())Journey.conflict("A current fully funded supplier confirmation is required for this document.");var d=jdbc.sql("select payload::text from journey_document_revision where booking_id=:id order by booking_version desc limit 1").param("id",id).query(String.class).optional().map(p->json.readValue(p,Journey.Document.class)).orElseGet(()->base.document(owner,id));if(!hash(d.content()).equals(d.sha256()))throw new IllegalStateException("Document integrity mismatch");return d;});}
 private Optional<Action> reviewed(Kind kind,UUID id){return jdbc.sql("select payload::text from journey_care_action where booking_id=:id and status='REVIEW' and payload->'booking'->'quote'->'selection'->'request'->>'kind'=:kind").param("id",id).param("kind",kind.name()).query(String.class).optional().map(p->json.readValue(p,Action.class));}
 public Optional<com.travbook.shared.domain.Recovery.Case> reviewCase(Kind kind,UUID id){return jdbc.sql("select a.payload::text from journey_care_action a where a.booking_id=:id and a.payload->'booking'->'quote'->'selection'->'request'->>'kind'=:kind and (a.status='REVIEW' or exists(select 1 from journey_care_recovery r where r.action_id=a.id)) order by (a.status='REVIEW') desc,(a.payload->'booking'->>'version')::bigint desc limit 1").param("id",id).param("kind",kind.name()).query(String.class).optional().map(p->json.readValue(p,Action.class)).map(a->{var b=base.booking(a.booking().quote().owner(),id);var actions=jdbc.sql("select payload::text from journey_care_recovery where action_id=:id order by id limit 3").param("id",a.id()).query(String.class).list().stream().map(p->json.readValue(p,com.travbook.shared.domain.Recovery.Action.class)).toList();boolean checkpoint=jdbc.sql("select count(*) from journey_care_review where action_id=:id and review_version=:v").param("id",a.id()).param("v",b.version()).query(Integer.class).single()==1;return new com.travbook.shared.domain.Recovery.Case(id,b.version(),b.status().name(),b.payment().name(),b.reservation().name(),b.refund().name(),a.type()+"_"+a.step(),checkpoint&&actions.size()<3&&a.status()==State.REVIEW&&b.status()==Status.REVIEW,b.updatedAt(),actions);});}
 public Action reviewCheckpoint(Kind kind,UUID id,long version){var a=reviewed(kind,id).orElseThrow(this::missing);return jdbc.sql("select action_payload::text from journey_care_review where action_id=:id and review_version=:v").param("id",a.id()).param("v",version).query(String.class).optional().map(p->json.readValue(p,Action.class)).orElseThrow(this::missing);}
 public Optional<com.travbook.shared.domain.Recovery.Action> recoveryReplay(String actor,String key,String f){return jdbc.sql("select fingerprint,payload::text from journey_care_recovery where actor=:actor and command_key=:key").param("actor",actor).param("key",key).query((r,n)->{if(!r.getString(1).equals(f))throw new DomainFailure(IDEMPOTENCY_CONFLICT,"Care recovery key changed.");return json.readValue(r.getString(2),com.travbook.shared.domain.Recovery.Action.class);}).optional();}
 public com.travbook.shared.domain.Recovery.Action resume(Kind kind,UUID id,long version,String actor,com.travbook.shared.domain.Recovery.Reason reason,String key,String f,UUID correlation){return tx.execute(t->{jdbc.sql("select pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","care-recovery:"+actor+":"+key).query((r,n)->true).single();var old=recoveryReplay(actor,key,f);if(old.isPresent())return old.get();var a=reviewed(kind,id).orElseThrow(this::missing);jdbc.sql("select action_id from journey_care_work where action_id=:id for update").param("id",a.id()).query(UUID.class).single();var b=lock(a.booking().quote().owner(),id);var c=reviewCase(kind,id).orElseThrow(this::missing);if(b.version()!=version||!c.recoverable())Journey.conflict("Care review changed or exhausted its recovery budget.");var previous=jdbc.sql("select booking_payload::text from journey_care_review where action_id=:id and review_version=:v").param("id",a.id()).param("v",version).query(String.class).single();var nextBooking=b.resumeCare(json.readValue(previous,Booking.class),clock.instant());var next=a.resumeFrom(reviewCheckpoint(kind,id,version),clock.instant());var action=new com.travbook.shared.domain.Recovery.Action(UUID.randomUUID(),id,nextBooking.version(),actor,reason,clock.instant());jdbc.sql("insert into journey_care_recovery(id,booking_id,action_id,actor,command_key,fingerprint,payload) values(:id,:b,:a,:actor,:key,:f,cast(:p as jsonb))").param("id",action.id()).param("b",id).param("a",a.id()).param("actor",actor).param("key",key).param("f",f).param("p",json.writeValueAsString(action)).update();saveBooking(nextBooking,b.version());saveAction(next,a.version());wake(next);if(next.type()==Type.BALANCE)jdbc.sql("update journey_balance set state='RUNNING' where booking_id=:id").param("id",id).update();event(next,action.id(),correlation);return action;});}
}
